mapper.select:
SELECT ae.*, a1.nickname as creator, a2.nickname as modifier FROM ai_experiment ae LEFT JOIN ab_user a1 ON ae.created_by_fk = a1.id LEFT JOIN ab_user a2 ON ae.changed_by_fk = a2.id
AND ae.project_id = #{projectId}
AND ae.status = #{status}
AND ae.model_name LIKE CONCAT('%', #{modelName}, '%')
AND a1.nickname LIKE CONCAT('%', #{creator}, '%')
ORDER BY ae.id DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM ai_experiment ae LEFT JOIN ab_user a1 ON ae.created_by_fk = a1.id
AND ae.project_id = #{projectId}
AND ae.status = #{status}
AND ae.model_name LIKE CONCAT('%', #{modelName}, '%')
AND a1.nickname LIKE CONCAT('%', #{creator}, '%')
